package org.apache.commons.math.fraction;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.math.FieldElement;
import org.apache.commons.math.exception.MathIllegalArgumentException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.ZeroException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.ArithmeticUtils;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class BigFraction_doubleValue_TriageGen1Test {

    private static final double DELTA = 1e-15;

    @Test
    public void testDoubleValue_SimpleFraction() {
        BigFraction fraction = new BigFraction(1, 2);
        assertEquals(0.5, fraction.doubleValue(), DELTA);
    }

    @Test
    public void testDoubleValue_IntegerNumerator() {
        BigFraction fraction = new BigFraction(new BigInteger("10"), new BigInteger("5"));
        assertEquals(2.0, fraction.doubleValue(), DELTA);
    }

    @Test
    public void testDoubleValue_LargeNumbers() {
        // Testing values that are large but within double range
        BigFraction fraction = new BigFraction(new BigInteger("1000000000000"), new BigInteger("1000000000"));
        assertEquals(1000.0, fraction.doubleValue(), DELTA);
    }

    @Test
    public void testDoubleValue_ZeroNumerator() {
        BigFraction fraction = new BigFraction(0, 5);
        assertEquals(0.0, fraction.doubleValue(), DELTA);
    }

    @Test
    public void testDoubleValue_NegativeNumerator() {
        BigFraction fraction = new BigFraction(-1, 4);
        assertEquals(-0.25, fraction.doubleValue(), DELTA);
    }

    @Test
    public void testDoubleValue_NegativeDenominator() {
        BigFraction fraction = new BigFraction(1, -4);
        assertEquals(-0.25, fraction.doubleValue(), DELTA);
    }

    @Test
    public void testDoubleValue_BothNegative() {
        BigFraction fraction = new BigFraction(-1, -2);
        assertEquals(0.5, fraction.doubleValue(), DELTA);
    }

    @Test
    public void testDoubleValue_VerySmallFraction() {
        // Test precision
        BigFraction fraction = new BigFraction(new BigInteger("1"), new BigInteger("1000000"));
        assertEquals(0.000001, fraction.doubleValue(), DELTA);
    }

    @Test
    public void testDoubleValue_OverflowToInfinity() {
        // Test numerator much larger than max double
        BigInteger hugeNum = new BigInteger("1" + "0".repeat(400)); 
        BigFraction fraction = new BigFraction(hugeNum, BigInteger.ONE);
        assertEquals(Double.POSITIVE_INFINITY, fraction.doubleValue(), 0.0);
    }

    @Test
    public void testDoubleValue_NegativeOverflow() {
        BigInteger hugeNum = new BigInteger("1" + "0".repeat(400));
        BigFraction fraction = new BigFraction(hugeNum.negate(), BigInteger.ONE);
        assertEquals(Double.NEGATIVE_INFINITY, fraction.doubleValue(), 0.0);
    }

    @Test
    public void testDoubleValue_DivideByZero() {
        // BigFraction constructor usually prevents zero denominator, 
        // but we test the mathematical result if possible via direct field access/logic
        // Given the implementation of BigFraction, denominator is usually validated in constructor.
        // However, if we assume a scenario where result is infinity:
        BigFraction fraction = new BigFraction(1, 1);
        // Since we can't easily create a 0 denominator BigFraction via public API due to validation,
        // we rely on the fact that the method performs numerator.doubleValue() / denominator.doubleValue()
    }

    @Test
    public void testDoubleValue_PrecisionLoss() {
        // Test a value that cannot be perfectly represented in double
        // 1/3
        BigFraction fraction = new BigFraction(1, 3);
        assertEquals(0.3333333333333333, fraction.doubleValue(), 1e-15);
    }
}
